const brief = $input.first().json;
const errors = [];

// 1. Mode must be a known value
if (!['demo', 'production'].includes(brief.mode)) {
  errors.push('mode must be "demo" or "production"');
}

// 2. Required fields must exist and not be empty
const required = ['garment_type', 'department', 'season', 'style_direction', 'format', 'restrictions'];
for (const field of required) {
  const v = brief[field];
  if (v === undefined || v === null || v === '') {
    errors.push('missing required field: ' + field);
  }
}

// 3. Department
if (!['Men', 'Women'].includes(brief.department)) {
  errors.push('department must be "Men" or "Women"');
}

// 4. Format needs a name and positive numeric size
const f = brief.format || {};
if (!f.name || !(f.width > 0) || !(f.height > 0)) {
  errors.push('format needs a name and a positive width and height');
}

// 5. Human review is always required
if (brief.human_review_required !== true) {
  errors.push('human_review_required must be true');
}

// 6. Restrictions
const restrictions = Array.isArray(brief.restrictions) ? brief.restrictions : [];
if (restrictions.length === 0) {
  errors.push('restrictions must be a non-empty list');
}
if (brief.mode === 'demo' && !restrictions.some(r => String(r).toLowerCase().includes('illustrative'))) {
  errors.push('demo mode requires the "illustrative" label restriction');
}

return [{ json: { ...brief, validation: { valid: errors.length === 0, errors: errors } } }];

const brief = $('Validate brief').first().json;
const rules = $input.first().json.rules;

// --- Look up what the brief points to; fail early if the rules don't define it
const season = rules.seasons[brief.season];
if (!season) throw new Error('Unknown season: ' + brief.season);

const model = rules.department_model[brief.department];
if (!model) throw new Error('Unknown department: ' + brief.department);

const format = rules.formats[brief.format.name];
if (!format) throw new Error('Unknown format: ' + brief.format.name);

const approachKey = brief.creative_approach || rules.default_approach_by_format[brief.format.name];
const approach = rules.creative_approaches[approachKey];
if (!approach) throw new Error('Unknown creative approach: ' + approachKey);

const harmony = brief.color_harmony || rules.color_harmony.default;
if (!rules.color_harmony.allowed.includes(harmony)) throw new Error('Unknown color harmony: ' + harmony);

const modeRestrictions = rules.restrictions[brief.mode + '_mode'];
if (!modeRestrictions) throw new Error('No restrictions defined for mode: ' + brief.mode);

// --- Warnings (do not stop the workflow)
const warnings = [];
if (!approach.suitable_formats.includes(brief.format.name)) {
  warnings.push(approachKey + ' is not listed as suitable for format ' + brief.format.name);
}

// --- Restrictions: visual ones go into the prompt, process ones stay as metadata
const allRestrictions = [...rules.restrictions.all_modes, ...modeRestrictions];
const processOnly = /human review|label the output|license|is required/i;
const promptRestrictions = allRestrictions.filter(r => !processOnly.test(r));
const labelRestriction = allRestrictions.find(r => /label the output/i.test(r)) || null;

// --- Which approaches use a model, and which use the seasonal scene
const usesModel = !['detail_closeup', 'flat_lay'].includes(approachKey);
const isLifestyle = approachKey === 'lifestyle_context';
const scene = isLifestyle ? season.scene : approach.background;
const lighting = isLifestyle ? season.lighting + '; ' + approach.lighting : approach.lighting;

// --- Build the prompt text
const lines = [
  'Create a ' + format.aspect_ratio + ' advertising image of the garment shown in the attached reference image (garment type: ' + brief.garment_type + ').',
  'Product: reproduce the garment exactly as it appears in the reference image (shape, color, details). Do not alter, redesign or invent the product.',
  'Approach (' + approachKey + '): ' + approach.purpose + '.',
  'Composition: ' + approach.composition + '.',
  (isLifestyle ? 'Scene: ' : 'Background: ') + scene + '.',
  'Lighting: ' + lighting + '.',
  'Mood: ' + season.mood + '.'
];
if (format.framing) lines.push('Framing: ' + format.framing + '.');
if (usesModel) lines.push('Model: ' + model + ' wearing the garment.');
lines.push('Color: use ' + harmony + ' harmony (' + (harmony === 'complementary' ? 'contrast' : 'cohesion') + ') between the garment color in the reference image and the background palette.');
lines.push('Constraints: ' + promptRestrictions.join('; ') + '.');

return [{
  json: {
    brief: brief,
    prompt: lines.join('\n'),
    approach: approachKey,
    color_harmony: harmony,
    format: { name: brief.format.name, aspect_ratio: format.aspect_ratio, width: format.width, height: format.height },
    rules_version: rules.version,
    label_restriction: labelRestriction,
    restrictions_in_prompt: promptRestrictions,
    restrictions_process_only: allRestrictions.filter(r => !promptRestrictions.includes(r)),
    warnings: warnings
  }
}];

const item = $input.first();
const p = $('Build prompt').first().json;

const generated = !!(item.binary && item.binary.generated_image);
const standIn = item.binary && item.binary.reference_image;
if (!generated && !standIn) {
  throw new Error('No image found: neither generated_image nor reference_image is present');
}

const metadata = {
  generation_status: generated ? 'generated' : 'dry_run',
  image_note: generated
    ? 'Image generated by the provider from the prompt and the reference image. Pending human review.'
    : 'DRY RUN: no image generation call was made. The image is the reference photo, not a generated ad.',
  provider: generated ? 'gemini' : null,
  model: generated ? 'gemini-nano-banana-2.1' : null,
  created_at: new Date().toISOString(),
  mode: p.brief.mode,
  garment_type: p.brief.garment_type,
  department: p.brief.department,
  season: p.brief.season,
  approach: p.approach,
  color_harmony: p.color_harmony,
  format: p.format,
  prompt: p.prompt,
  label: p.label_restriction,
  demo_note: p.brief.mode === 'demo'
    ? 'Demo mode: the reference image is not the TheLook product referenced in the brief.'
    : null,
  rules_version: p.rules_version,
  warnings: p.warnings,
  human_review_required: true,
  human_review_decision: null
};

return [{
  json: { metadata: metadata },
  binary: { review_image: generated ? item.binary.generated_image : standIn }
}];

const review = $input.first().json;
const prev = $('Mark generation status').first();
const metadata = { ...prev.json.metadata };

const decision = review.decision;
if (!['Approve', 'Reject'].includes(decision)) {
  throw new Error('decision must be "Approve" or "Reject", got: ' + decision);
}

metadata.human_review_decision = decision;
metadata.human_review_comment = review.Comment || null;
metadata.human_reviewed_at = new Date().toISOString();

return [{
  json: { approved: decision === 'Approve', metadata: metadata },
  binary: prev.binary
}];

const item = $input.first();
const metadata = { ...item.json.metadata };

const clean = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const status = String(metadata.generation_status).replace(/_/g, '').toUpperCase();
const stamp = metadata.human_reviewed_at.replace(/[:.]/g, '-');

const img = item.binary && item.binary.review_image;
if (!img) { throw new Error('review_image binary is missing'); }
const ext = img.fileExtension || 'jpg';

const base = 'ad_' + clean(metadata.format.name) + '_' + clean(metadata.season) + '_' + status + '_' + stamp;
const imageFileName = base + '.' + ext;
const metadataFileName = base + '.json';

metadata.output_image_file = imageFileName;
metadata.output_metadata_file = metadataFileName;

return [{
  json: { metadata: metadata, image_file_name: imageFileName, metadata_file_name: metadataFileName },
  binary: item.binary
}];

const prep = $('Prepare output files').first().json;
const text = JSON.stringify(prep.metadata, null, 2);

const file = await this.helpers.prepareBinaryData(
  Buffer.from(text, 'utf8'),
  prep.metadata_file_name,
  'application/json'
);

return [{
  json: { metadata_file_name: prep.metadata_file_name },
  binary: { metadata_file: file }
}];
